const db = require('../connection');
const EMP='empresa-mutti-001'; const PID='2536ebcf-f124-4a6b-bda4-7da8c401e673';
const P = {"nome":"Verão com Mutti — A energia que vende","tema":"verao","ano":2026,"chamada":"Sol lá fora, brilho aqui dentro.","contexto":"O verão é a estação da vibração, da alegria e do movimento — e a Mutti leva essa energia pras ruas, feiras e praças com o Verão Mutti Protegido: saúde, autocuidado e proteção de forma leve, participativa e divertida. A ideia é mobilizar a comunidade, gerar conteúdo real e transformar o ponto de venda em ponto de experiência.","mercado":"8 lojas · Entre Rios, Esplanada, Inhambupe e Rio Real (interior da Bahia)","periodo":"Planejamento out · ativações nov · digital dez–jan · encerramento no Mutti Day (fev)","pracas":"Entre Rios · Esplanada · Inhambupe · Rio Real","frequencia":"Ativações ao longo do verão (Mutti na Feira, Aulões, Desafio) + conteúdo digital contínuo","formato":"Ações ao vivo + redes + PDV temático Verão Mutti Protegido","cota_tipo":"Master / Co-patrocinador / Apoiador Local","investimento":5000,"investimento_obs":"A partir de R$ 5.000 (Apoiador Local). Cotas: Master R$ 15.000 · Co-patrocinador R$ 7.000 · Apoiador Local R$ 5.000.","provas_json":"[{\"n\":\"+5.000\",\"l\":\"pessoas impactadas presencialmente\"},{\"n\":\"+50 mil\",\"l\":\"visualizações esperadas nas redes\"},{\"n\":\"Sol lá fora,\",\"l\":\"brilho aqui dentro\"}]","formatos_json":"[\"Mutti na Feira — Estação do Cuidado (tenda + amostragem)\",\"Aulões Mutti Protegido (alongamento/dança ao ar livre)\",\"Desafio Verão Mutti (#VeraoMuttiProtegido)\",\"Vitrine e pontas de gôndola temáticas\",\"Brindes Mutti Protegido (squeeze/chapéu/nécessaire)\",\"Reels, stories e mini entrevistas\",\"Registro audiovisual pra redes e B2B\"]","faq_json":"[{\"q\":\"Quando acontece?\",\"a\":\"Ao longo do verão: planejamento em out, primeiras ativações em nov, conteúdo digital de dez a jan e encerramento no Mutti Day em fev.\"},{\"q\":\"Quais as cotas?\",\"a\":\"Master (R$ 15.000), Co-patrocinador (R$ 7.000) e Apoiador Local (R$ 5.000) — cada uma com um nível de exposição.\"},{\"q\":\"Como mede o resultado?\",\"a\":\"Sell-out por loja no ERP (antes × depois) + alcance presencial e digital. Nome e CPF de cliente nunca são compartilhados.\"}]","por_que":"O verão é o momento mais importante do ano pra vendas de proteção solar e hidratação. O Verão Mutti Protegido conecta a sua marca a esse pico, em ações reais com o público — não é visibilidade comprada, é presença no cuidado.","o_que_mostrar":"Mutti na Feira (tenda, amostras, dicas), Aulões Mutti Protegido (ao ar livre), Desafio Verão Mutti (#VeraoMuttiProtegido), PDV e vitrine temáticos, reels/stories e mini entrevistas.","publico":"+5.000 pessoas impactadas presencialmente · +50 mil visualizações esperadas nas redes · 86 mil clientes identificados no grupo.","produtos_foco":"Protetor solar, hidratantes, vitaminas, repelentes e cuidados de verão.","sellout_potencial":"O verão é o pico de proteção solar e hidratação; a sua categoria cresce no período — apuração de sell-out por loja no ERP (antes × depois).","oportunidades":"Patrocínio Master (logo em destaque, distribuição principal de amostras), Co-patrocinador (peças digitais, tenda e stories) e Apoiador Local (amostragem e material impresso). Registro audiovisual pra uso em redes e B2B.","conteudo_redes":"#VeraoMuttiProtegido · reels/stories das ações · mini entrevistas de autocuidado · @farmaciamutti_ + influenciadores.","midias_on":"Reels/stories, publicações oficiais Mutti e challenge #VeraoMuttiProtegido.","midias_off":"Tenda Mutti na Feira, aulões ao ar livre, vitrine e pontas de gôndola temáticas, banners/windbanners e amostragem.","midias_online":"Conteúdo digital contínuo (dez–jan) + registro audiovisual pra redes e B2B.","veic_ini":"2026-11-01","veic_fim":"2027-02-28","capa_foto":"data:image/jpeg;base64,","status":"publicado","destaque":1};
const COTAS = [{"id":"e90c9e6d-3320-452d-8406-90fff9ebaa81","nome":"Master","preco":15000,"quantidade":1,"cor":"#E8871E","ordem":0},{"id":"21aa55d9-53f4-4371-8171-b177c178f08d","nome":"Co-patrocinador","preco":7000,"quantidade":3,"cor":"#F2C200","ordem":1},{"id":"05a39ad4-2484-4a7a-9188-c31589a8b28e","nome":"Apoiador Local","preco":5000,"quantidade":6,"cor":"#2E8BC0","ordem":2}];
const FOTOS = [{"id":"0c5140a5-836e-4bbe-813f-e2f2d2fc34ab","foto":"data:image/jpeg;base64,","legenda":"Sol lá fora, brilho aqui dentro — as ativações do verão","ordem":0,"secao":"galeria"},{"id":"4bd77a48-54f1-40f2-9d6f-3212cb639eba","foto":"data:image/jpeg;base64,","legenda":"Alcance e benefícios para os parceiros","ordem":1,"secao":"galeria"},{"id":"fd334500-6cb0-4a3f-978f-0d360c00fae7","foto":"data:image/jpeg;base64,","legenda":"Cotas de patrocínio","ordem":2,"secao":"galeria"}];
try {
  if (!db.prepare('SELECT 1 FROM tmkt_plano WHERE id=? AND empresa_id=?').get(PID, EMP)) { console.log('↷ migration 280: plano Verão não existe ainda — ok'); }
  else {
    const cols = Object.keys(P);
    db.prepare('UPDATE tmkt_plano SET ' + cols.map(c=>c+'=?').join(', ') + ' WHERE id=? AND empresa_id=?').run(...cols.map(c=>P[c]), PID, EMP);
    db.prepare('DELETE FROM tmkt_plano_cotas WHERE plano_id=?').run(PID);
    const ic = db.prepare("INSERT OR IGNORE INTO tmkt_plano_cotas (id,empresa_id,plano_id,nome,preco,quantidade,cor,ordem,criado_em) VALUES (?,?,?,?,?,?,?,?,datetime('now'))");
    for (const c of COTAS) ic.run(c.id, EMP, PID, c.nome, c.preco, c.quantidade, c.cor, c.ordem);
    db.prepare("DELETE FROM tmkt_plano_fotos WHERE plano_id=? AND secao='galeria'").run(PID);
    const if2 = db.prepare("INSERT OR IGNORE INTO tmkt_plano_fotos (id,empresa_id,plano_id,foto,legenda,ordem,secao,criado_em) VALUES (?,?,?,?,?,?,?,datetime('now'))");
    for (const f of FOTOS) if2.run(f.id, EMP, PID, f.foto, f.legenda, f.ordem, f.secao);
    console.log('✅ migration 280: plano Verão real aplicado (' + COTAS.length + ' cotas, ' + FOTOS.length + ' fotos)');
  }
} catch (e) { if (!/no such table/i.test(e.message)) throw e; console.log('↷ migration 280: tabelas ainda não existem — ok'); }
